function cdqOuvrirPdfCommeSheetV2275(id){
  const pref=cdqPdfReaderPreference();

  if(pref==='cdq'){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(navigator.onLine===false){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  cdqMarquerPdfOuvertV2275(id);

  const meta=cdqDocumentMeta(id)||{};
  const fallback=cdqPdfDriveUrlV2275(id);
  const nativeIntent=
    'intent://open?fileId='+encodeURIComponent(String(id||''))+
    '&name='+encodeURIComponent(String(meta.nom||'Rapport.pdf'))+
    '&reader='+encodeURIComponent(String(pref||'ask'))+
    '#Intent;scheme=cdqpdf;package=ca.balancecdq.android;'+
    'S.browser_fallback_url='+encodeURIComponent(fallback)+';end';

  window.location.href=nativeIntent;
  return true;
}
